class FEMenu;
class FEMenuEntry;

class FEEntityManager
{
public:
	void ToMainScreen();
	void ResumeCameraRoll();
};

class GraphicalMenuSystem;

class FEManager
{
	char padding[0x148];
public:
	FEEntityManager* em;
	GraphicalMenuSystem* gms;
	char padding2[0x1566c - 0x150];
	int tmp_game_mode;
};

class FEMenuEntry
{
public:
	int entry_num;
	virtual void SetNoFlash(bool);
};

class FEMenu
{
public:
	int center_x;
	int center_y;
	int num_entries;
	int dy;
	int half;
	int menu_num;
	char padding[0x40];
	FEMenuEntry* highlighted;
	char padding2[0x0c];
	FEMenu* active;
	virtual void setHigh(FEMenuEntry*, bool = true);
};

class FEMultiMenu : public FEMenu
{
public:
	virtual void OnActivate();
};

class FEGraphicalMenu : public FEMultiMenu
{
};

class OptionsMenu : public FEGraphicalMenu
{
public:
	virtual void setPQMain(bool, bool = false);
};

class BeachFrontEnd : public FEGraphicalMenu
{
public:
	void ResetFirstTime();
};

class GraphicalMenuSystem
{
public:
	enum
	{
		MainMenu,
		ExtrasMenu,
		CreditsMenu,
		HighScoreMenu,
		SurferMenu,
		BeachMenu
	};
	char padding[0xc8];
	int active;
	FEMenu* menus[15];
};

enum
{
	GAME_MODE_CAREER,
	GAME_MODE_FREESURF_INFINITE,
	GAME_MODE_FREESURF_HIGHSCORE,
	GAME_MODE_FREESURF_ICON,
	GAME_MODE_PRACTICE,
	GAME_MODE_TIME_ATTACK,
	GAME_MODE_METER_ATTACK,
	GAME_MODE_SEA_HORSE,
	GAME_MODE_HEAD_TO_HEAD,
	GAME_MODE_PUSH
};

class MainFrontEnd : public FEMultiMenu
{
public:
	enum
	{
		MainFreeEntry,
		MainCareerEntry,
		MainMultiEntry,
		MainExtrasEntry,
		MainOpEntry,
		MainEnd
	};
private:
	FEManager* manager;
	GraphicalMenuSystem* sys;
	FEMenuEntry* entry_list[MainEnd];
	char padding[0x104];
public:
	OptionsMenu* Options;
	void OnActivate();
	void MakeActive(FEMenu*);
	void UpdateHighlight();
	int returnToHighlighted;
};

void MainFrontEnd::OnActivate()
{
	manager->em->ToMainScreen();
	manager->em->ResumeCameraRoll();
	Options->setPQMain(false, true);
	FEMenu* ac_before = active;

	// if Freesurf or Multiplayer were the last active menus before another screen
	// was activated (SurferMenu) then re-activate them
	if(active && active != Options && active->menu_num != manager->gms->active)
		MakeActive((FEGraphicalMenu*) active);
	else
	{
		FEMultiMenu::OnActivate();
		if(sys->active == GraphicalMenuSystem::ExtrasMenu)
			setHigh(entry_list[MainExtrasEntry]);
		else
		{
			// if previous active was Options, highlight options entry
			if(ac_before == Options)
				setHigh(entry_list[MainOpEntry]);
			else if (returnToHighlighted != -1)
			{
				highlighted = entry_list[MainCareerEntry];
				returnToHighlighted = -1;
			}
			else
			{
				switch(manager->tmp_game_mode)
				{
				case GAME_MODE_CAREER: setHigh(entry_list[MainCareerEntry]); break;
				case GAME_MODE_FREESURF_INFINITE:
				case GAME_MODE_FREESURF_HIGHSCORE:
				case GAME_MODE_FREESURF_ICON:	setHigh(entry_list[MainFreeEntry]); break;
				case GAME_MODE_TIME_ATTACK:
				case GAME_MODE_HEAD_TO_HEAD:
				case GAME_MODE_PUSH: setHigh(entry_list[MainMultiEntry]); break;
				default: break;
				}
			}
		}
		UpdateHighlight();

		// if we go all the way back to main screen, then the mode might change, so 
		// we'll need to re-find the proper beach
		((BeachFrontEnd*) sys->menus[GraphicalMenuSystem::BeachMenu])->ResetFirstTime();
	}

	entry_list[MainFreeEntry]->SetNoFlash(true);
	entry_list[MainMultiEntry]->SetNoFlash(true);
	entry_list[MainCareerEntry]->SetNoFlash(true);
}
